<template>
  <!-- 文创商城页面 - 精选非遗文创产品 -->
  <div class="shop-view">
    <!-- 页面头部区域 -->
    <section class="page-header">
      <div class="header-content">
        <h1 class="page-title">文创商城</h1>
        <p class="page-subtitle">精选非遗文创产品，让传统文化融入现代生活</p>
      </div>
    </section>

    <div class="shop-container">
      <!-- 筛选排序工具栏 -->
      <div class="toolbar">
        <!-- 分类筛选 -->
        <div class="category-filters">
          <button
            v-for="cat in categories"
            :key="cat.value"
            class="filter-btn"
            :class="{ active: currentCategory === cat.value }"
            @click="setCategory(cat.value)"
          >
            {{ cat.label }}
          </button>
        </div>
        <!-- 排序选项 -->
        <div class="sort-bar">
          <span class="sort-label">排序：</span>
          <select v-model="sortBy" class="sort-select">
            <option v-for="opt in sortOptions" :key="opt.value" :value="opt.value">
              {{ opt.label }}
            </option>
          </select>
        </div>
      </div>

      <!-- 加载状态 -->
      <LoadingSpinner v-if="loading && !products.length" />

      <!-- 空状态 -->
      <EmptyState
        v-else-if="!sortedProducts.length"
        title="暂无商品"
        description="当前分类下没有商品，看看其他分类吧"
      />

      <!-- 商品网格 -->
      <TransitionGroup v-else name="products" tag="div" class="products-grid">
        <div
          v-for="product in paginatedProducts"
          :key="product.id"
          class="product-wrapper"
        >
          <ProductCard :product="product" />
          <button
            class="add-cart-btn"
            :disabled="product.stock <= 0"
            @click="addToCart(product)"
          >
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
              <path
                d="M3 1h2l.4 2M5 3h8l-1.2 6H5.6M5.6 9L4 13h9"
                stroke="currentColor"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              />
              <circle cx="6" cy="14" r="1" fill="currentColor" />
              <circle cx="12" cy="14" r="1" fill="currentColor" />
            </svg>
            {{ product.stock > 0 ? '加入购物车' : '已售罄' }}
          </button>
        </div>
      </TransitionGroup>

      <!-- 分页 -->
      <div v-if="totalPages > 1" class="pagination">
        <button
          class="page-btn"
          :disabled="currentPage === 1"
          @click="currentPage--"
        >
          上一页
        </button>
        <span
          v-for="page in visiblePages"
          :key="page"
          class="page-number"
          :class="{ active: currentPage === page }"
          @click="currentPage = page"
        >
          {{ page }}
        </span>
        <button
          class="page-btn"
          :disabled="currentPage === totalPages"
          @click="currentPage++"
        >
          下一页
        </button>
      </div>
    </div>

    <!-- 浮动购物车按钮 -->
    <div class="floating-cart" @click="goToCart">
      <div class="cart-icon">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <path
            d="M4 5h2l2 11h10l2-8H8"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
          />
          <circle cx="10" cy="20" r="1.5" fill="currentColor" />
          <circle cx="18" cy="20" r="1.5" fill="currentColor" />
        </svg>
      </div>
      <span v-if="cartCount > 0" class="cart-badge">{{ cartCount }}</span>
    </div>

    <!-- Toast 提示 -->
    <Transition name="toast">
      <div v-if="showToast" class="toast-notification">
        <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
          <path d="M3 9l4 4 8-8" stroke="#27AE60" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
        </svg>
        <span>已加入购物车</span>
      </div>
    </Transition>
  </div>
</template>

<script setup>
/**
 * ShopView.vue - 文创商城页面
 *
 * 功能说明：
 * - 展示非遗文创产品网格
 * - 支持8个分类筛选（全部/刺绣/漆器/挑花/编钟/武术/皮影/其他）
 * - 支持5种排序方式（默认/价格/销量/评分）
 * - 响应式网格布局：4列->3列->2列->1列
 * - 浮动购物车按钮，显示商品数量
 * - 每个卡片带有"加入购物车"按钮
 * - Toast提示加入购物车成功
 * - 分页、加载状态和空状态
 */
import { ref, computed, onMounted } from 'vue'
import { useStore } from 'vuex'
import { useRouter } from 'vue-router'
import ProductCard from '@/components/ProductCard.vue'
import LoadingSpinner from '@/components/LoadingSpinner.vue'
import EmptyState from '@/components/EmptyState.vue'

// 获取 Vuex store 和 router 实例
const store = useStore()
const router = useRouter()

// ==================== 响应式状态 ====================

/** 当前选中的分类 */
const currentCategory = ref('all')
/** 当前排序方式 */
const sortBy = ref('default')
/** 当前页码 */
const currentPage = ref(1)
/** 每页商品数量 */
const pageSize = ref(12)
/** 是否显示Toast提示 */
const showToast = ref(false)
/** Toast定时器 */
let toastTimer = null

// ==================== 分类和排序配置 ====================

/** 商品分类选项 */
const categories = [
  { label: '全部', value: 'all' },
  { label: '刺绣', value: '刺绣' },
  { label: '漆器', value: '漆器' },
  { label: '挑花', value: '挑花' },
  { label: '编钟', value: '编钟' },
  { label: '武术', value: '武术' },
  { label: '皮影', value: '皮影' },
  { label: '其他', value: '其他' }
]

/** 排序选项 */
const sortOptions = [
  { label: '默认', value: 'default' },
  { label: '价格从低到高', value: 'price-asc' },
  { label: '价格从高到低', value: 'price-desc' },
  { label: '销量优先', value: 'sales' },
  { label: '评分最高', value: 'rating' }
]

// ==================== 计算属性 ====================

/** 从 Vuex store 获取加载状态 */
const loading = computed(() => store.state.loading)

/** 从 Vuex store 获取商品列表 */
const products = computed(() => store.state.products || [])

/** 购物车商品数量 */
const cartCount = computed(() => store.getters.cartCount || 0)

/** 根据分类筛选后的商品列表 */
const filteredProducts = computed(() => {
  if (currentCategory.value === 'all') return products.value
  return products.value.filter(p => p.category === currentCategory.value)
})

/** 筛选并排序后的商品列表 */
const sortedProducts = computed(() => {
  const list = [...filteredProducts.value]
  switch (sortBy.value) {
    case 'price-asc':
      return list.sort((a, b) => (a.price || 0) - (b.price || 0))
    case 'price-desc':
      return list.sort((a, b) => (b.price || 0) - (a.price || 0))
    case 'sales':
      return list.sort((a, b) => (b.sales || 0) - (a.sales || 0))
    case 'rating':
      return list.sort((a, b) => (b.rating || 0) - (a.rating || 0))
    default:
      return list
  }
})

/** 分页后的商品列表 */
const paginatedProducts = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  const end = start + pageSize.value
  return sortedProducts.value.slice(start, end)
})

/** 总页数 */
const totalPages = computed(() => Math.ceil(sortedProducts.value.length / pageSize.value))

/** 可见的页码范围 */
const visiblePages = computed(() => {
  const pages = []
  const max = totalPages.value
  const current = currentPage.value
  let start = Math.max(1, current - 2)
  let end = Math.min(max, current + 2)
  if (end - start < 4) {
    if (start === 1) end = Math.min(max, start + 4)
    else if (end === max) start = Math.max(1, end - 4)
  }
  for (let i = start; i <= end; i++) pages.push(i)
  return pages
})

// ==================== 方法 ====================

/**
 * 设置当前分类，并重置页码
 * @param {string} value - 分类值
 */
const setCategory = (value) => {
  currentCategory.value = value
  currentPage.value = 1
}

/**
 * 将商品加入购物车
 * @param {Object} product - 商品数据
 */
const addToCart = (product) => {
  store.commit('ADD_TO_CART', product)
  showToastMessage()
}

/**
 * 显示Toast提示，3秒后自动隐藏
 */
const showToastMessage = () => {
  showToast.value = true
  if (toastTimer) clearTimeout(toastTimer)
  toastTimer = setTimeout(() => {
    showToast.value = false
  }, 3000)
}

/**
 * 跳转到购物车页面
 */
const goToCart = () => {
  router.push('/cart')
}

// ==================== 生命周期 ====================

onMounted(async () => {
  try {
    await store.dispatch('fetchProducts')
  } catch (err) {
    console.error('获取商品列表失败:', err)
  }
})
</script>

